void Init(JNIEnv *env, jobject thiz, jobject ctx, jobject title, jobject subtitle) {
    //Judul menu
    setText(env, title, OBFUSCATE("<b>Mod Menu by Asterix</b>"));

    //Teks berjalan di bawah judul
    setText(env, subtitle, OBFUSCATE("<b><marquee><p style=\"font-size:30px\">"
                                     "<p style=\"color:green;\">Modded by Asterix</p>"
                                     " | Jangan lupa Subscribe</p>"
                                     "</marquee></b>"));

    //Dialog sambutan (dimatiin, bikin crash dari Service)
    //Dialog(env,
    //       ctx,
    //       OBFUSCATE("Mod Menu by Asterix"),
    //       OBFUSCATE("Jangan lupa istirahat."),
    //       nullptr,
    //       OBFUSCATE("Tutup"),
    //       3,
    //       nullptr);

    //Toast saat menu terbuka
    Toast(env, ctx, OBFUSCATE("Modded by Asterix"), ToastLength::LENGTH_LONG);
}

